import{_ as h,I as e,o as p,c,b6 as l,j as a,J as s,w as n,a as i}from"./chunks/framework.BUXTSoD9.js";const y=JSON.parse('{"title":"Dify 유사 지능체 플랫폼 개발 실전","description":"","frontmatter":{},"headers":[],"relativePath":"ko-kr/stage-2/assignments/custom-dify-agent-platform/index.md","filePath":"ko-kr/stage-2/assignments/custom-dify-agent-platform/index.md"}'),b={name:"ko-kr/stage-2/assignments/custom-dify-agent-platform/index.md"},k={style:{margin:"32px 0"}};function u(g,t,f,m,_,E){const r=e("StepBar"),d=e("ClientOnly"),o=e("el-card");return p(),c("div",null,[t[2]||(t[2]=l('<h1 id="dify-유사-지능체-플랫폼-개발-실전" tabindex="-1">Dify 유사 지능체 플랫폼 개발 실전 <a class="header-anchor" href="#dify-유사-지능체-플랫폼-개발-실전" aria-label="Permalink to “Dify 유사 지능체 플랫폼 개발 실전”">​</a></h1><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to “개요”">​</a></h2><p>이 실전 프로젝트에서는 실제 PRD를 바탕으로 Dify의 핵심 경험을 모방한 지능체 플랫폼을 처음부터 완성하게 됩니다. 사용자 콘솔, 관리 대시보드, 플랫폼 백엔드를 구축하고, 지능체 관리, 대화, 로깅, 지식 베이스 등의 핵심 기능을 구현하게 됩니다.</p><p>이 프로젝트는 Stage 2의 종합 실전环节입니다. 앞선 단일 페이지 또는 단일 기능 프로젝트와 달리, &quot;플랫폼 감&quot;이 있는 AI 제품을 구축해야 합니다. 다중 역할, 다중 모듈, 데이터 영속화, 모델 호출 체인이 포함됩니다.</p><h2 id="사전-지식" tabindex="-1">사전 지식 <a class="header-anchor" href="#사전-지식" aria-label="Permalink to “사전 지식”">​</a></h2><p>이 프로젝트를 시작하기 전에 다음 내용을 이미 숙지하고 있어야 합니다:</p><ul><li>프론트엔드 페이지 디자인 및 컴포넌트 라이브러리 사용 (<a href="./../../frontend/ui-design/">UI 디자인</a>, <a href="./../../frontend/modern-component-library/">모던 컴포넌트 라이브러리</a>)</li><li>백엔드 API 설계 및 개발 (<a href="./../../backend/ai-interface-code/">API 코드 작성</a>)</li><li>데이터베이스 기초와 Supabase (<a href="./../../backend/database-supabase/">데이터베이스부터 Supabase까지</a>)</li><li>Git 워크플로우 및 배포 (<a href="./../../backend/git-workflow/">Git과 GitHub</a>, <a href="./../../backend/zeabur-deployment/">웹 애플리케이션 배포</a>)</li></ul><h2 id="학습-목표" tabindex="-1">학습 목표 <a class="header-anchor" href="#학습-목표" aria-label="Permalink to “학습 목표”">​</a></h2><p>이 실전을 완료하면 다음을 할 수 있게 됩니다:</p><ol><li>실제 PRD를 읽고 이해하여 개발 작업 목록을 추출하기</li><li>지능체 플랫폼의 페이지 아키텍처와 데이터 모델 설계하기</li><li>지능체 생성, 대화, 로그 기록의 완전한 파이프라인 구현하기</li><li>AI 보조를 활용하여 플랫폼형 제품 개발을 완료하기</li><li>엔드투엔드 연동 테스트를 완료하고 데모 가능한 AI 플랫폼 프로토타입을 전달하기</li></ol><h2 id="프로젝트-소개" tabindex="-1">프로젝트 소개 <a class="header-anchor" href="#프로젝트-소개" aria-label="Permalink to “프로젝트 소개”">​</a></h2><p>구축할 제품은 Dify 유사 지능체 플랫폼으로, 두 개의 하위 시스템을 포함합니다:</p><table tabindex="0"><thead><tr><th>하위 시스템</th><th>역할</th></tr></thead><tbody><tr><td><strong>사용자 콘솔</strong></td><td>지능체 생성, Prompt 설정, 대화 시작, 로그 확인, 지식 베이스 관리</td></tr><tr><td><strong>관리 대시보드</strong></td><td>사용자 데이터, 플랫폼 리소스 사용 현황, 호출 통계 확인</td></tr></tbody></table><p>백엔드는 다음 핵심 역량을 지원해야 합니다: 지능체 관리, 세션 관리, 메시지 저장, 모델 호출, 호출 로그 기록, 지식 베이스 연동.</p><div class="tip custom-block"><p class="custom-block-title">PRD 입구</p><p>이 프로젝트의 요구사항 문서는 GitHub에 있습니다: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/ko-kr/stage-2/assignments/custom-dify-agent-platform/PRD.md" target="_blank" rel="noreferrer">PRD 보기</a></p></div>',15)),a("div",k,[s(d,null,{default:n(()=>[s(r,{active:0,items:[{title:"요구사항 분석",description:"PRD를 읽고 페이지, 역량 범위, 인증, 데이터 모델을 명확히 합니다"},{title:"골격 구축",description:"AI로 사용자 콘솔과 관리 대시보드 골격을 생성합니다"},{title:"반복 개발",description:"모듈별로 지능체, 대화, 로그, 지식 베이스를 추가합니다"},{title:"연동 및 배포",description:"엔드투엔드로 실행하고, 배포하여 데모를 준비합니다"}]})]),_:1})]),t[3]||(t[3]=l(`<h2 id="제1부-요구사항-분석" tabindex="-1">제1부: 요구사항 분석 <a class="header-anchor" href="#제1부-요구사항-분석" aria-label="Permalink to “제1부: 요구사항 분석”">​</a></h2><h3 id="_1-1-prd-읽기" tabindex="-1">1.1 PRD 읽기 <a class="header-anchor" href="#_1-1-prd-읽기" aria-label="Permalink to “1.1 PRD 읽기”">​</a></h3><p>PRD 문서를 열고 다음 질문에 중점적으로 답해보세요:</p><ul><li>지능체, 세션, 로그, 지식 베이스 중 MVP에 포함할 것은 무엇인가?</li><li>페이지와 라우팅 목록이 확정되었는가?</li><li>모델 호출과 로그 기록의 범위는 무엇인가?</li><li>멀티 테넌시와 복잡한 워크플로우는 일단 제외하는가?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>위 질문들에 명확한 답이 없다면, 코드 작성을 시작하지 마세요. 요구사항 이해가 불충분한 것은 재작업의 가장 흔한 원인입니다.</p></div><h3 id="_1-2-시스템-아키텍처-확인" tabindex="-1">1.2 시스템 아키텍처 확인 <a class="header-anchor" href="#_1-2-시스템-아키텍처-확인" aria-label="Permalink to “1.2 시스템 아키텍처 확인”">​</a></h3><p>PRD에 따라 시스템의 전체 아키텍처를 정리하세요:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; app[&quot;사용자 콘솔&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;관리 대시보드&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;인증&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; agent[&quot;지능체 설정&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; chat[&quot;세션 대화&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  chat --&gt; llm[&quot;모델 호출&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  chat --&gt; db[&quot;데이터베이스&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; kb[&quot;지식 베이스 연동&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; logs[&quot;호출 로그 및 플랫폼 개요&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  logs --&gt; db</span></span></code></pre></div><h2 id="제2부-프로젝트-골격-구축" tabindex="-1">제2부: 프로젝트 골격 구축 <a class="header-anchor" href="#제2부-프로젝트-골격-구축" aria-label="Permalink to “제2부: 프로젝트 골격 구축”">​</a></h2><h3 id="_2-1-프론트엔드-페이지-생성" tabindex="-1">2.1 프론트엔드 페이지 생성 <a class="header-anchor" href="#_2-1-프론트엔드-페이지-생성" aria-label="Permalink to “2.1 프론트엔드 페이지 생성”">​</a></h3><p>프롬프트 참고:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>현재 PRD를 바탕으로 Dify 유사 지능체 플랫폼의 프론트엔드 골격을 생성해 주세요.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>요구사항:</span></span>
<span class="line"><span>1. 사용자 측 구성: 로그인, 지능체 목록, 지능체 설정, 대화 페이지, 로그 페이지, 지식 베이스 페이지</span></span>
<span class="line"><span>2. 관리 측 구성: 관리 홈페이지, 사용자 개요, 리소스 사용 개요</span></span>
<span class="line"><span>3. 먼저 페이지 구조와 가짜 데이터만 생성하고, 실제 API는 연결하지 않습니다</span></span>
<span class="line"><span>4. 모던 AI 플랫폼 같은 스타일</span></span></code></pre></div><h3 id="_2-2-페이지-구조-확인" tabindex="-1">2.2 페이지 구조 확인 <a class="header-anchor" href="#_2-2-페이지-구조-확인" aria-label="Permalink to “2.2 페이지 구조 확인”">​</a></h3><p>항목별 확인:</p><ul><li>[ ] 사용자 콘솔과 관리 대시보드 진입점이 분리되어 있는가</li><li>[ ] 지능체 목록, 설정, 대화, 로그, 지식 베이스 페이지가 완전한가</li><li>[ ] 관리 대시보드 홈페이지, 사용자 개요 페이지에 접근 가능한가</li><li>[ ] 가짜 데이터가 기본 UI 상태를 표시하는가</li></ul><h2 id="제3부-반복-개발" tabindex="-1">제3부: 반복 개발 <a class="header-anchor" href="#제3부-반복-개발" aria-label="Permalink to “제3부: 반복 개발”">​</a></h2><h3 id="_3-1-모듈별-진행" tabindex="-1">3.1 모듈별 진행 <a class="header-anchor" href="#_3-1-모듈별-진행" aria-label="Permalink to “3.1 모듈별 진행”">​</a></h3><p>골격을 기반으로 다음 순서대로 모듈별로 기능을 추가합니다:</p><ol><li><strong>인증</strong>: 회원가입, 로그인, 역할 구분</li><li><strong>지능체 관리</strong>: 생성, 편집, 삭제, Prompt 설정</li><li><strong>대화 기능</strong>: 세션 생성, 메시지 송수신, 모델 호출</li><li><strong>로그 기록</strong>: 소요 시간, token 사용량, 오류 기록</li><li><strong>지식 베이스 연동</strong> (보너스): 문서 업로드, 검색, 결과 주입</li><li><strong>관리 대시보드</strong>: 사용자 데이터, 리소스 사용, 호출 통계</li></ol><p>각 모듈 완료 후 다음 표로 자체 점검:</p><table tabindex="0"><thead><tr><th>점검 항목</th><th>검증 방법</th></tr></thead><tbody><tr><td>페이지 일관성</td><td>페이지 수, 기능이 PRD에 부합하는가</td></tr><tr><td>API 루프</td><td>agents, chat, logs, knowledge API가 완전한가</td></tr><tr><td>권한 격리</td><td>사용자가 자신의 agent와 세션만 관리할 수 있는가</td></tr><tr><td>데이터 일관성</td><td>messages, logs, documents 데이터가 서로 일치하는가</td></tr><tr><td>데모 가능성</td><td>&quot;agent 생성 → 대화 → 로그 확인&quot; 완전한 파이프라인을 데모할 수 있는가</td></tr></tbody></table><h3 id="_3-2-지식-베이스-연동-보너스" tabindex="-1">3.2 지식 베이스 연동 (보너스) <a class="header-anchor" href="#_3-2-지식-베이스-연동-보너스" aria-label="Permalink to “3.2 지식 베이스 연동 (보너스)”">​</a></h3><p>지식 베이스 역량을 추가하고 싶다면, 각 지능체에 &quot;지식 베이스 스위치&quot;를 추가할 수 있습니다:</p><ul><li>활성화하면 먼저 지식 조각을 검색한 다음, 사용자 질문과 함께 모델에 전송합니다</li><li>비활성화하면 일반 대화 모드로 응답합니다</li></ul><p>첫 번째 버전에서는 복잡한 RAG를 추구할 필요가 없으며, &quot;검색 결과가 보이고, 호출 파이프라인이 설명 가능하면&quot; 충분합니다.</p><h2 id="제4부-연동-및-배포" tabindex="-1">제4부: 연동 및 배포 <a class="header-anchor" href="#제4부-연동-및-배포" aria-label="Permalink to “제4부: 연동 및 배포”">​</a></h2><h3 id="_4-1-엔드투엔드-테스트" tabindex="-1">4.1 엔드투엔드 테스트 <a class="header-anchor" href="#_4-1-엔드투엔드-테스트" aria-label="Permalink to “4.1 엔드투엔드 테스트”">​</a></h3><p>최소한 다음 시나리오를 검증하세요:</p><ul><li>회원가입 → 지능체 생성 → Prompt 설정 → 대화 시작 → 로그 확인</li><li>관리자 로그인 → 사용자 데이터 확인 → 호출 통계 확인</li></ul><p>배포 전 점검:</p><ul><li>[ ] 모든 핵심 API에 로그인 검증이 적용되었는가</li><li>[ ] 지능체 소유권 권한 검증을 통과했는가</li><li>[ ] 세션 기록, 로그 기록이 실제로 데이터베이스에 저장되는가</li><li>[ ] 모델 Key가 환경 변수를 사용하고, 하드코딩되지 않았는가</li><li>[ ] 오류 메시지가 프론트엔드에서 확인 가능하고, 콘솔에만 출력되지 않는가</li></ul><h3 id="_4-2-배포" tabindex="-1">4.2 배포 <a class="header-anchor" href="#_4-2-배포" aria-label="Permalink to “4.2 배포”">​</a></h3><p>프로젝트를 공개 네트워크 환경에 배포합니다. 배포 튜토리얼 참고: <a href="./../../backend/git-workflow/">Git 및 GitHub 워크플로우</a>, <a href="./../../backend/zeabur-deployment/">웹 애플리케이션 배포 방법</a>.</p><h2 id="산출물" tabindex="-1">산출물 <a class="header-anchor" href="#산출물" aria-label="Permalink to “산출물”">​</a></h2><p>이 프로젝트를 완료한 후 다음을 제출해야 합니다:</p><ul><li>[ ] 접근 가능한 온라인 데모 링크</li><li>[ ] 소스 코드 저장소 링크 (README 포함)</li><li>[ ] PRD 문서</li><li>[ ] 핵심 페이지 스크린샷 (지능체 관리 페이지, 대화 페이지, 로그 페이지, 관리 홈페이지)</li><li>[ ] 60초 데모 영상 (지능체 생성 → 대화 → 로그 확인 포함)</li></ul><p>README에는 최소한 다음이 포함되어야 합니다: 프로젝트 소개, 아키텍처 설명, 기술 스택, 로컬 실행 단계, 환경 변수 목록, API 설명.</p><h2 id="평가-기준" tabindex="-1">평가 기준 <a class="header-anchor" href="#평가-기준" aria-label="Permalink to “평가 기준”">​</a></h2><table tabindex="0"><thead><tr><th>영역</th><th>기본 요구사항</th><th>심화 요구사항</th></tr></thead><tbody><tr><td>플랫폼 완성도</td><td>agents / chat / logs 세 페이지 사용 가능</td><td>명확한 탐색과 통일된 디자인 언어가 있음</td></tr><tr><td>비즈니스 루프</td><td>지능체를 생성하고 실제 대화가 가능함</td><td>다중 지능체 전환과 과거 세션 지원</td></tr><tr><td>데이터 및 추적</td><td>메시지와 호출 로그를 조회할 수 있음</td><td>token / 소요 시간 통계 대시보드가 있음</td></tr><tr><td>권한 보안</td><td>로그인한 사용자만 핵심 API에 접근 가능</td><td>리소스 소유권 검증이 완비됨</td></tr><tr><td>엔지니어링 전달</td><td>배포 가능, 데모 가능, README가 명확함</td><td>지식 베이스 연동 및 검색 결과 설명 가능</td></tr></tbody></table><h2 id="제출-전-점검" tabindex="-1">제출 전 점검 <a class="header-anchor" href="#제출-전-점검" aria-label="Permalink to “제출 전 점검”">​</a></h2>`,40)),s(o,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:n(()=>[...t[0]||(t[0]=[a("div",{style:{"font-weight":"bold","font-size":"16px"}},"제출 전 마지막 확인",-1)])]),default:n(()=>[t[1]||(t[1]=a("ul",{style:{"list-style-type":"none","padding-left":"0"}},[a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 로그인 후 지능체 관리, 대화, 로그 페이지에 접근 가능")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 최소 1개의 지능체를 생성하고 성공적으로 대화 가능")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 각 질문/답변이 데이터베이스에서 조회 가능")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 호출 실패 시 프론트엔드에서 오류 정보를 확인할 수 있고 로그가 기록됨")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 프로젝트가 배포되었고, README와 데모 영상이 완비됨")])])],-1))]),_:1}),t[4]||(t[4]=l('<h2 id="참고-자료" tabindex="-1">참고 자료 <a class="header-anchor" href="#참고-자료" aria-label="Permalink to “참고 자료”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 디자인</a></li><li><a href="./../../frontend/modern-component-library/">모던 컴포넌트 라이브러리로 인터페이스 업데이트하기</a></li><li><a href="./../../backend/database-supabase/">데이터베이스부터 Supabase까지</a></li><li><a href="./../../backend/ai-interface-code/">대형 언어 모델로 API 코드 및 문서 작성하기</a></li><li><a href="./../../backend/git-workflow/">Git 및 GitHub 워크플로우</a></li><li><a href="./../../backend/zeabur-deployment/">웹 애플리케이션 배포 방법</a></li></ul>',2))])}const x=h(b,[["render",u]]);export{y as __pageData,x as default};
